```python
def my_sort(nums):
    n = len(nums)

    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if nums[j] < nums[min_idx]:
                min_idx = j
        nums[i], nums[min_idx] = nums[min_idx], nums[i]

    return nums

nums = [5, 3, 8, 2, 9, 4]
print(my_sort(nums))  # Output: [2, 3, 4, 5, 8, 9]
```

