def count_words(text):
    """
    This function takes a string 'text' as input and returns a dictionary with each unique word from the text as keys,
    and the number of occurrences of that word as values.

    Usage examples:
    >>> count_words("Hello World")
    {'hello': 1, 'world': 1}

    >>> count_words("The quick brown fox")
    {'the': 1, 'quick': 1, 'brown': 1, 'fox': 1}
    """
    words = text.split()  # Split the string into individual words
    word_count_dict = {}

    for word in words:
        if word in word_count_dict:
            word_count_dict[word] += 1  # Increment the count if the word is already in the dictionary
        else:
            word_count_dict[word] = 1

    return word_count_dict

# Example usage
example_text = "One phrase, two phrases, three phrases."
print(count_words(example_text))
